import asyncio

from app.auth.passwords import DUMMY_HASH, password_hash
from app.auth.repository import PgUserRepository, User


class AuthService:
    def __init__(self, users: PgUserRepository) -> None:
        self.users = users

    async def sign_up(self, email: str, name: str, password: str) -> User:
        hashed = await asyncio.to_thread(password_hash.hash, password)
        return await self.users.insert(email, name, hashed)

    async def authenticate(self, email: str, password: str) -> User | None:
        user = await self.users.get_by_email(email)
        if user is None or user.password_hash is None:
            await asyncio.to_thread(password_hash.verify, password, DUMMY_HASH)
            return None
        valid, new_hash = await asyncio.to_thread(
            password_hash.verify_and_update, password, user.password_hash
        )
        if not valid:
            return None
        if new_hash is not None:
            await self.users.update_password_hash(user.id, new_hash)
        return user

SAFE_METHODS = {"GET", "HEAD", "OPTIONS"}


def same_origin_only(trusted_origins: set[str]):
    async def check(request: Request) -> None:
        if request.method in SAFE_METHODS:
            return
        site = request.headers.get("sec-fetch-site")
        if site in ("same-origin", "none"):
            return
        origin = request.headers.get("origin")
        if origin in trusted_origins:
            return
        if site is None and origin is None:
            return
        raise ForbiddenError("Cross-site requests can't change anything here.")

    return check

